// Monta, a partir do POST de /api/leads, os textos do aviso e da resposta.
const ROTULOS = {"segmento":{"automotivo":"Revenda de veículos","servicos":"Serviços","comercio":"Comércio","imobiliario":"Imobiliário","saude":"Saúde","industria":"Indústria","outro":"Outro"},"porte":{"1":"Só eu","2-5":"2 a 5 pessoas","6-20":"6 a 20 pessoas","21+":"Mais de 20"},"objetivos":{"aparecer":"Aparecer no Google e no Maps","contatos":"Mais contatos do site e dos anúncios","responder":"Responder mais rápido no WhatsApp","funil":"Organizar o funil e o CRM","integrar":"Integrar os sistemas que já uso","marca":"Rever a marca"},"estoque":{"ate-30":"Até 30 veículos","31-80":"31 a 80","81-150":"81 a 150","151+":"Mais de 150"},"sistema":{"revenda-mais":"Revenda Mais","autoconf":"Autoconf","bndv":"BNDV","boom":"Boom","outro":"Outro","nenhum":"Nenhum"}};
const corpo = $input.first().json.body || {};
const lead = corpo.lead || {};
const origem = lead.origem || {};
const rotulo = (grupo, valor) => (valor ? ROTULOS[grupo][valor] || valor : "");

const whatsapp = String(lead.whatsapp || "").replace(/\D/g, "");
const semPais = whatsapp.replace(/^55/, "");
const meio = semPais.length === 11 ? 7 : 6;
const whatsappLegivel = semPais ? "(" + semPais.slice(0, 2) + ") " + semPais.slice(2, meio) + "-" + semPais.slice(meio) : "";
const primeiroNome = String(lead.nome || "").trim().split(/\s+/)[0] || "";
const objetivos = (lead.objetivos || []).map((o) => rotulo("objetivos", o));

const partesDaOrigem = [];
if (origem.gclid || origem.gbraid || origem.wbraid) partesDaOrigem.push("Google Ads");
if (origem.fbclid) partesDaOrigem.push("Meta Ads");
if (origem.utm_source) partesDaOrigem.push("utm: " + [origem.utm_source, origem.utm_medium, origem.utm_campaign].filter(Boolean).join(" / "));
if (origem.referrer) partesDaOrigem.push("veio de " + origem.referrer);
if (origem.entrada) partesDaOrigem.push("entrou em " + origem.entrada);
const origemResumo = partesDaOrigem.length ? partesDaOrigem.join(" · ") : "direta (sem parâmetro de campanha)";

const linhasDoAviso = [
  "Novo pedido de diagnóstico pelo site",
  "Nome: " + lead.nome,
  "Empresa: " + lead.empresa,
  "WhatsApp: " + whatsappLegivel + " (https://wa.me/" + whatsapp + ")",
  "E-mail: " + lead.email,
  "Segmento: " + rotulo("segmento", lead.segmento) + (lead.porte ? " · Porte: " + rotulo("porte", lead.porte) : ""),
  objetivos.length ? "Objetivos: " + objetivos.join("; ") : "",
  lead.estoque ? "Estoque: " + rotulo("estoque", lead.estoque) + (lead.sistema ? " · Sistema: " + rotulo("sistema", lead.sistema) : "") : "",
  lead.mensagem ? "Mensagem: " + lead.mensagem : "",
  "Origem: " + origemResumo,
  lead.pagina ? "Página: " + lead.pagina : "",
  "Evento: " + corpo.event_id,
].filter(Boolean);

const respostaParaLead = [
  "Olá, " + primeiroNome + "! Aqui é a V2O5. Recebemos seu pedido de diagnóstico para a " + lead.empresa + ".",
  "O próximo passo é marcar os 45 minutos com o Dyones, fundador da V2O5. Que dia e horário ficam bons para você?",
  "Depois da conversa, o mapa do que fazer primeiro chega em até 24 horas.",
].join("\n\n");

return [{
  json: {
    event_id: corpo.event_id,
    recebido_em: corpo.recebido_em,
    nome: lead.nome,
    primeiroNome,
    empresa: lead.empresa,
    whatsapp,
    whatsappInternacional: "+" + whatsapp,
    whatsappLegivel,
    email: lead.email,
    segmento: rotulo("segmento", lead.segmento),
    porte: rotulo("porte", lead.porte),
    objetivos: objetivos.join("; "),
    estoque: rotulo("estoque", lead.estoque),
    sistema: rotulo("sistema", lead.sistema),
    mensagem: lead.mensagem || "",
    pagina: lead.pagina || "",
    origem,
    origemResumo,
    avisoParaDyones: linhasDoAviso.join("\n"),
    respostaParaLead,
  },
}];
